import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { Project, AboutData } from './types';
import { INITIAL_PROJECTS, INITIAL_ABOUT } from './data';

// Pages
import Home from './pages/Home';
import Projects from './pages/Projects';
import ProjectDetail from './pages/ProjectDetail';
import About from './pages/About';
import Contact from './pages/Contact';
import Admin from './pages/Admin';

const Navbar: React.FC = () => {
  const location = useLocation();
  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className="sticky top-0 z-50 bg-[#111111]/90 backdrop-blur-md border-b border-white/5">
      <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
        <Link to="/" className="text-xl font-bold tracking-tighter hover:opacity-70 transition-opacity">
          HEEJI WOO
        </Link>
        <div className="flex gap-8 text-sm font-medium tracking-wide">
          <Link to="/" className={`${isActive('/') ? 'text-white' : 'text-gray-400'} hover:text-white transition-colors`}>HOME</Link>
          <Link to="/projects" className={`${isActive('/projects') ? 'text-white' : 'text-gray-400'} hover:text-white transition-colors`}>PROJECTS</Link>
          <Link to="/about" className={`${isActive('/about') ? 'text-white' : 'text-gray-400'} hover:text-white transition-colors`}>ABOUT</Link>
          <Link to="/contact" className={`${isActive('/contact') ? 'text-white' : 'text-gray-400'} hover:text-white transition-colors`}>CONTACT</Link>
          <Link to="/admin" className="text-gray-600 hover:text-gray-400 ml-4">ADMIN</Link>
        </div>
      </div>
    </nav>
  );
};

const Footer: React.FC = () => (
  <footer className="py-12 px-6 border-t border-white/5 mt-20">
    <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-6">
      <p className="text-gray-500 text-sm">© 2024 Heeji Woo. All rights reserved.</p>
      <div className="flex gap-6 text-gray-500 text-sm">
        <a href="#" className="hover:text-white transition-colors">ArtStation</a>
        <a href="#" className="hover:text-white transition-colors">LinkedIn</a>
        <a href="#" className="hover:text-white transition-colors">Vimeo</a>
      </div>
    </div>
  </footer>
);

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>(() => {
    const saved = localStorage.getItem('hw_projects');
    return saved ? JSON.parse(saved) : INITIAL_PROJECTS;
  });

  const [about, setAbout] = useState<AboutData>(() => {
    const saved = localStorage.getItem('hw_about');
    return saved ? JSON.parse(saved) : INITIAL_ABOUT;
  });

  useEffect(() => {
    localStorage.setItem('hw_projects', JSON.stringify(projects));
  }, [projects]);

  useEffect(() => {
    localStorage.setItem('hw_about', JSON.stringify(about));
  }, [about]);

  return (
    <HashRouter>
      <div className="min-h-screen flex flex-col bg-[#111111]">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/projects" element={<Projects projects={projects} />} />
            <Route path="/projects/:id" element={<ProjectDetail projects={projects} />} />
            <Route path="/about" element={<About data={about} />} />
            <Route path="/contact" element={<Contact />} />
            <Route path="/admin" element={<Admin projects={projects} setProjects={setProjects} about={about} setAbout={setAbout} />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </HashRouter>
  );
};

export default App;

