import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { Project } from '../types';

interface ProjectDetailProps {
  projects: Project[];
}

const ProjectDetail: React.FC<ProjectDetailProps> = ({ projects }) => {
  const { id } = useParams<{ id: string }>();
  const project = projects.find(p => p.id === id);

  if (!project) {
    return (
      <div className="max-w-7xl mx-auto px-6 py-32 text-center">
        <h2 className="text-2xl mb-4">Project not found</h2>
        <Link to="/projects" className="text-blue-400 hover:underline">Back to projects</Link>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-6 py-16 fade-in">
      <Link to="/projects" className="text-xs text-gray-500 hover:text-white mb-12 inline-block uppercase tracking-[0.2em]">
        ← Back to all projects
      </Link>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-12 mb-20">
        <div className="lg:col-span-1 space-y-6">
          <h1 className="text-4xl font-bold tracking-tighter text-white">{project.title}</h1>
          <div className="space-y-4">
            <div>
              <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">Role</p>
              <p className="text-gray-300">{project.role}</p>
            </div>
            <div>
              <p className="text-xs text-gray-500 uppercase tracking-widest mb-1">Year</p>
              <p className="text-gray-300">{project.year}</p>
            </div>
          </div>
          <p className="text-gray-400 leading-relaxed pt-4 border-t border-white/5">
            {project.description}
          </p>
        </div>

        <div className="lg:col-span-2 space-y-8">
          {project.images.map((img, idx) => (
            <div key={idx} className="bg-white/5 border border-white/10 rounded-sm overflow-hidden">
              <img src={img} alt={`${project.title} detail ${idx + 1}`} className="w-full" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ProjectDetail;

