import React, { useState } from 'react';
import { Project, AboutData } from '../types';

interface AdminProps {
  projects: Project[];
  setProjects: React.Dispatch<React.SetStateAction<Project[]>>;
  about: AboutData;
  setAbout: React.Dispatch<React.SetStateAction<AboutData>>;
}

const Admin: React.FC<AdminProps> = ({ projects, setProjects, about, setAbout }) => {
  const [password, setPassword] = useState('');
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [activeTab, setActiveTab] = useState<'projects' | 'about'>('projects');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === 'admin9987') {
      setIsAuthorized(true);
    } else {
      alert('Incorrect Password');
    }
  };

  const addProject = () => {
    const newProj: Project = {
      id: Date.now().toString(),
      title: 'New Project',
      role: 'Role Name',
      year: new Date().getFullYear().toString(),
      thumbnail: 'https://picsum.photos/id/101/1280/720',
      description: 'Project description here...',
      images: ['https://picsum.photos/id/102/1280/720']
    };
    setProjects([newProj, ...projects]);
  };

  const deleteProject = (id: string) => {
    if (confirm('Delete this project?')) {
      setProjects(projects.filter(p => p.id !== id));
    }
  };

  const updateProject = (id: string, field: keyof Project, value: any) => {
    setProjects(projects.map(p => p.id === id ? { ...p, [field]: value } : p));
  };

  if (!isAuthorized) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center p-6 fade-in">
        <form onSubmit={handleLogin} className="w-full max-w-sm space-y-4 bg-white/5 p-8 border border-white/10">
          <h2 className="text-xl font-bold uppercase tracking-widest mb-6">Admin Login</h2>
          <input 
            type="password" 
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="w-full bg-[#111] border border-white/10 px-4 py-2 rounded focus:outline-none focus:border-white/30"
          />
          <button type="submit" className="w-full bg-white text-black py-2 font-bold uppercase tracking-widest text-sm">
            Unlock
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-6 py-16 fade-in">
      <div className="flex justify-between items-center mb-12">
        <h1 className="text-3xl font-bold uppercase tracking-tighter">Content Management</h1>
        <div className="flex gap-4">
          <button 
            onClick={() => setActiveTab('projects')}
            className={`px-4 py-2 text-sm uppercase tracking-widest font-bold ${activeTab === 'projects' ? 'border-b-2 border-white' : 'text-gray-500'}`}
          >
            Projects
          </button>
          <button 
            onClick={() => setActiveTab('about')}
            className={`px-4 py-2 text-sm uppercase tracking-widest font-bold ${activeTab === 'about' ? 'border-b-2 border-white' : 'text-gray-500'}`}
          >
            About
          </button>
        </div>
      </div>

      {activeTab === 'projects' && (
        <div className="space-y-12">
          <button 
            onClick={addProject}
            className="w-full border-2 border-dashed border-white/10 py-6 text-gray-500 hover:text-white hover:border-white/30 transition-all uppercase tracking-widest text-sm"
          >
            + Add New Project
          </button>

          {projects.map((p) => (
            <div key={p.id} className="p-8 bg-white/5 border border-white/10 space-y-6 relative group">
              <button 
                onClick={() => deleteProject(p.id)}
                className="absolute top-4 right-4 text-red-500 opacity-0 group-hover:opacity-100 transition-opacity uppercase text-xs font-bold"
              >
                Delete
              </button>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div>
                    <label className="text-xs text-gray-500 uppercase tracking-widest">Title</label>
                    <input 
                      className="w-full bg-transparent border-b border-white/10 py-2 focus:outline-none focus:border-white"
                      value={p.title}
                      onChange={(e) => updateProject(p.id, 'title', e.target.value)}
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500 uppercase tracking-widest">Role</label>
                    <input 
                      className="w-full bg-transparent border-b border-white/10 py-2 focus:outline-none focus:border-white"
                      value={p.role}
                      onChange={(e) => updateProject(p.id, 'role', e.target.value)}
                    />
                  </div>
                </div>
                <div className="space-y-4">
                  <div>
                    <label className="text-xs text-gray-500 uppercase tracking-widest">Year</label>
                    <input 
                      className="w-full bg-transparent border-b border-white/10 py-2 focus:outline-none focus:border-white"
                      value={p.year}
                      onChange={(e) => updateProject(p.id, 'year', e.target.value)}
                    />
                  </div>
                  <div>
                    <label className="text-xs text-gray-500 uppercase tracking-widest">Thumbnail URL</label>
                    <input 
                      className="w-full bg-transparent border-b border-white/10 py-2 focus:outline-none focus:border-white"
                      value={p.thumbnail}
                      onChange={(e) => updateProject(p.id, 'thumbnail', e.target.value)}
                    />
                  </div>
                </div>
              </div>
              <div>
                <label className="text-xs text-gray-500 uppercase tracking-widest">Description</label>
                <textarea 
                  className="w-full bg-transparent border border-white/10 p-4 mt-2 h-32 focus:outline-none focus:border-white/30"
                  value={p.description}
                  onChange={(e) => updateProject(p.id, 'description', e.target.value)}
                />
              </div>
            </div>
          ))}
        </div>
      )}

      {activeTab === 'about' && (
        <div className="space-y-12">
          <div className="p-8 bg-white/5 border border-white/10 space-y-6">
            <h3 className="text-xl font-bold uppercase tracking-widest">Biography</h3>
            <div>
              <label className="text-xs text-gray-500 uppercase tracking-widest">Profile Image URL</label>
              <input 
                className="w-full bg-transparent border-b border-white/10 py-2 focus:outline-none focus:border-white"
                value={about.profileImage}
                onChange={(e) => setAbout({ ...about, profileImage: e.target.value })}
              />
            </div>
            <div>
              <label className="text-xs text-gray-500 uppercase tracking-widest">Intro Text</label>
              <textarea 
                className="w-full bg-transparent border border-white/10 p-4 mt-2 h-40 focus:outline-none focus:border-white/30"
                value={about.intro}
                onChange={(e) => setAbout({ ...about, intro: e.target.value })}
              />
            </div>
          </div>
          <p className="text-center text-xs text-gray-600 italic">Experience and Tools are hardcoded for this prototype version's safety.</p>
        </div>
      )}

      <div className="mt-12 text-center">
        <p className="text-sm text-green-500 font-mono">Changes are saved automatically to Local Storage.</p>
      </div>
    </div>
  );
};

export default Admin;

