const Lightbox: React.FC<{ 
  images: string[], 
  isOpen: boolean, 
  onClose: () => void, 
  initialIndex: number 
}> = ({ images, isOpen, onClose, initialIndex }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);

  useEffect(() => {
    setCurrentIndex(initialIndex);
  }, [initialIndex]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowRight') next();
      if (e.key === 'ArrowLeft') prev();
    };
    if (isOpen) window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, currentIndex]);

  const next = () => setCurrentIndex((prev) => (prev + 1) % images.length);
  const prev = () => setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black flex items-center justify-center p-4">
      <button onClick={onClose} className="absolute top-8 right-8 text-white/50 hover:text-white text-4xl z-[110] transition-colors">&times;</button>
      <button onClick={prev} className="absolute left-8 top-1/2 -translate-y-1/2 text-white/50 hover:text-white text-5xl z-[110] transition-colors p-4">&lsaquo;</button>
      <button onClick={next} className="absolute right-8 top-1/2 -translate-y-1/2 text-white/50 hover:text-white text-5xl z-[110] transition-colors p-4">&rsaquo;</button>

      <div className="w-full h-full flex items-center justify-center">
        <img 
          src={images[currentIndex]} 
          alt="Full screen render" 
          className="max-w-full max-h-full object-contain select-none"
        />
      </div>

      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 text-white/30 text-xs tracking-widest uppercase">
        {currentIndex + 1} / {images.length}
      </div>
    </div>
  );
};

