const Lightbox: React.FC<{ 
  images: string[], 
  isOpen: boolean, 
  onClose: () => void, 
  initialIndex: number 
}> = ({ images, isOpen, onClose, initialIndex }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);

  useEffect(() => {
    setCurrentIndex(initialIndex);
  }, [initialIndex]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowRight') next();
      if (e.key === 'ArrowLeft') prev();
    };
    if (isOpen) window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, currentIndex]);

  const next = () => setCurrentIndex((prev) => (prev + 1) % images.length);
  const prev = () => setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-slate-950/98 backdrop-blur-2xl flex items-center justify-center p-10 transition-all">
      <button onClick={onClose} className="absolute top-12 right-12 text-white/20 hover:text-blue-400 text-4xl z-[110] transition-colors">&times;</button>
      <button onClick={prev} className="absolute left-12 top-1/2 -translate-y-1/2 text-white/10 hover:text-blue-400 text-7xl z-[110] transition-colors p-6">&lsaquo;</button>
      <button onClick={next} className="absolute right-12 top-1/2 -translate-y-1/2 text-white/10 hover:text-blue-400 text-7xl z-[110] transition-colors p-6">&rsaquo;</button>

      <div className="w-full h-full flex items-center justify-center p-4">
        <img 
          src={images[currentIndex]} 
          alt="Full screen render" 
          className="max-w-full max-h-full object-contain select-none shadow-[0_0_120px_rgba(37,99,235,0.2)] reveal active"
        />
      </div>

      <div className="absolute bottom-12 left-1/2 -translate-x-1/2 flex items-center gap-6">
        <span className="text-blue-500 font-mono text-sm font-bold tracking-[0.5em] uppercase">
          {currentIndex + 1}
        </span>
        <span className="w-12 h-[1px] bg-white/10"></span>
        <span className="text-gray-700 font-mono text-sm font-bold tracking-[0.5em] uppercase">
          {images.length}
        </span>
      </div>
    </div>
  );
};

