const Lightbox: React.FC<{ 
  images: string[], 
  isOpen: boolean, 
  onClose: () => void, 
  initialIndex: number 
}> = ({ images, isOpen, onClose, initialIndex }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);

  useEffect(() => {
    setCurrentIndex(initialIndex);
  }, [initialIndex]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowRight') next();
      if (e.key === 'ArrowLeft') prev();
    };
    if (isOpen) window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, currentIndex]);

  const next = () => setCurrentIndex((prev) => (prev + 1) % images.length);
  const prev = () => setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black/98 flex items-center justify-center p-8 transition-all">
      <button onClick={onClose} className="absolute top-10 right-10 text-white/30 hover:text-blue-500 text-3xl z-[110] transition-colors">&times;</button>
      <button onClick={prev} className="absolute left-10 top-1/2 -translate-y-1/2 text-white/10 hover:text-blue-500 text-6xl z-[110] transition-colors p-4">&lsaquo;</button>
      <button onClick={next} className="absolute right-10 top-1/2 -translate-y-1/2 text-white/10 hover:text-blue-400 text-6xl z-[110] transition-colors p-4">&rsaquo;</button>

      <div className="w-full h-full flex items-center justify-center">
        <img 
          src={images[currentIndex]} 
          alt="Full screen render" 
          className="max-w-full max-h-full object-contain select-none shadow-2xl reveal active"
        />
      </div>

      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 text-blue-900 text-[10px] tracking-[0.5em] uppercase font-bold">
        {currentIndex + 1} <span className="text-gray-800 mx-2">/</span> {images.length}
      </div>
    </div>
  );
};

