import React, { useState, useEffect, useCallback, useRef } from 'react';
import { HashRouter, Routes, Route, Link, useLocation, useNavigate } from 'react-router-dom';
import { Project, AboutData } from './types';
import { INITIAL_PROJECTS, INITIAL_ABOUT } from './data';

// Pages
import Home from './pages/Home';
import ProjectDetail from './pages/ProjectDetail';
import Admin from './pages/Admin';

const Navbar: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [activeSection, setActiveSection] = useState('home');
  const isScrollingRef = useRef(false);
  const scrollTimeoutRef = useRef<number | null>(null);

  // 현재 활성 섹션 추적 (Scroll Spy)
  useEffect(() => {
    if (location.pathname !== '/') {
      setActiveSection('');
      return;
    }

    const observerOptions = {
      root: null,
      rootMargin: '-45% 0px -45% 0px', // 화면 중앙 영역 기준
      threshold: 0
    };

    const observerCallback = (entries: IntersectionObserverEntry[]) => {
      // 클릭에 의한 자동 스크롤 중에는 관찰자 업데이트를 무시하여 색상이 튀는 현상 방지
      if (isScrollingRef.current) return;

      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    };

    const observer = new IntersectionObserver(observerCallback, observerOptions);
    const sectionIds = ['home', 'projects', 'about', 'contact'];

    sectionIds.forEach(id => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    const handleManualScroll = () => {
      if (isScrollingRef.current) return;
      if (window.scrollY < 100) {
        setActiveSection('home');
      }
    };

    window.addEventListener('scroll', handleManualScroll);
    return () => {
      observer.disconnect();
      window.removeEventListener('scroll', handleManualScroll);
    };
  }, [location.pathname]);

  const scrollToSection = useCallback((id: string) => {
    const performScroll = () => {
      const el = document.getElementById(id);
      if (el) {
        const offset = 80; // 네비바 높이
        const elementPosition = el.getBoundingClientRect().top + window.pageYOffset;
        const offsetPosition = elementPosition - offset;

        // 1. 상태 즉시 변경 (UI 피드백)
        isScrollingRef.current = true;
        setActiveSection(id);

        // 2. 스크롤 실행
        window.scrollTo({
          top: id === 'home' ? 0 : offsetPosition,
          behavior: 'smooth'
        });

        // 3. 기존 타이머 제거 후 스크롤 완료 감지용 타이머 설정
        if (scrollTimeoutRef.current) window.clearTimeout(scrollTimeoutRef.current);
        scrollTimeoutRef.current = window.setTimeout(() => {
          isScrollingRef.current = false;
        }, 1000); // 스크롤 애니메이션 시간을 고려한 넉넉한 타임아웃
      }
    };

    if (location.pathname !== '/') {
      navigate('/');
      // 페이지 이동 후 DOM이 렌더링될 시간 부여
      setTimeout(performScroll, 100);
    } else {
      performScroll();
    }
  }, [location.pathname, navigate]);

  const navLinkClass = (id: string) => {
    const isActive = activeSection === id;
    return `${isActive ? 'text-blue-500' : 'text-gray-500'} hover:text-white transition-all duration-300 uppercase cursor-pointer relative py-2 text-[11px] md:text-[12px] font-bold tracking-[0.2em] outline-none`;
  };

  return (
    <nav className="fixed top-0 left-0 w-full z-50 nav-solid h-20 flex items-center">
      <div className="max-w-[1800px] mx-auto w-full px-8 md:px-16 flex items-center justify-between">
        <button 
          onClick={() => scrollToSection('home')}
          className="text-xl font-bold tracking-[-0.05em] hover:opacity-80 transition-all uppercase text-blue-500 cursor-pointer"
        >
          HJ
        </button>
        <div className="flex gap-6 md:gap-12 items-center">
          <button onClick={() => scrollToSection('home')} className={navLinkClass('home')}>
            HOME
            {activeSection === 'home' && <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-1 h-1 bg-blue-500 rounded-full"></span>}
          </button>
          <button onClick={() => scrollToSection('projects')} className={navLinkClass('projects')}>
            PROJECTS
            {activeSection === 'projects' && <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-1 h-1 bg-blue-500 rounded-full"></span>}
          </button>
          <button onClick={() => scrollToSection('about')} className={navLinkClass('about')}>
            ABOUT
            {activeSection === 'about' && <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-1 h-1 bg-blue-500 rounded-full"></span>}
          </button>
          <button onClick={() => scrollToSection('contact')} className={navLinkClass('contact')}>
            CONTACT
            {activeSection === 'contact' && <span className="absolute bottom-0 left-1/2 -translate-x-1/2 w-1 h-1 bg-blue-500 rounded-full"></span>}
          </button>
        </div>
      </div>
    </nav>
  );
};

