const Lightbox: React.FC<{ 
  images: string[], 
  isOpen: boolean, 
  onClose: () => void, 
  initialIndex: number 
}> = ({ images, isOpen, onClose, initialIndex }) => {
  const [currentIndex, setCurrentIndex] = useState(initialIndex);

  useEffect(() => {
    setCurrentIndex(initialIndex);
  }, [initialIndex]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'ArrowRight') next();
      if (e.key === 'ArrowLeft') prev();
    };
    if (isOpen) {
      document.body.style.overflow = 'hidden';
      window.addEventListener('keydown', handleKeyDown);
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, currentIndex]);

  const next = () => setCurrentIndex((prev) => (prev + 1) % images.length);
  const prev = () => setCurrentIndex((prev) => (prev - 1 + images.length) % images.length);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] bg-black/98 flex items-center justify-center p-4 md:p-12 transition-all backdrop-blur-sm">
      <button 
        onClick={onClose} 
        className="absolute top-8 right-8 text-white/40 hover:text-white text-4xl z-[210] transition-colors p-4 cursor-pointer"
        aria-label="Close Lightbox"
      >
        &times;
      </button>

      {images.length > 1 && (
        <>
