        </>
      )}

      <div className="w-full h-full flex items-center justify-center animate-fade-in" onClick={(e) => e.target === e.currentTarget && onClose()}>
        <img 
          src={images[currentIndex]} 
          alt={`Render ${currentIndex + 1}`} 
          className="max-w-full max-h-full object-contain select-none shadow-2xl rounded-lg"
        />
      </div>

      {images.length > 1 && (
        <div className="absolute bottom-8 left-1/2 -translate-x-1/2 text-white/30 text-[11px] tracking-[0.6em] uppercase font-bold">
          {currentIndex + 1} <span className="text-white/10 mx-3">/</span> {images.length}
        </div>
      )}
    </div>
  );
};

