        <p className="text-blue-500 font-bold tracking-tight text-lg uppercase">HEEJI WOO</p>
        <p className="text-gray-600 text-[10px] uppercase tracking-[0.4em] font-bold">© 2024 — 3D Character Artist for Production</p>
      </div>
