import React, { useState } from 'react';
import { Project, AboutData, HomeData, ContactData, ToolCategory, Experience } from '../types';

interface AdminProps {
  projects: Project[];
  setProjects: React.Dispatch<React.SetStateAction<Project[]>>;
  about: AboutData;
  setAbout: React.Dispatch<React.SetStateAction<AboutData>>;
  home: HomeData;
  setHome: React.Dispatch<React.SetStateAction<HomeData>>;
  contact: ContactData;
  setContact: React.Dispatch<React.SetStateAction<ContactData>>;
}

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] text-gray-500 uppercase tracking-widest block mb-2 font-bold">{children}</label>
);

const Input = (props: React.InputHTMLAttributes<HTMLInputElement>) => (
  <input {...props} className={`w-full bg-[#111] border border-white/10 px-4 py-3 text-white focus:outline-none focus:border-blue-500/30 rounded-xl ${props.className || ''}`} />
);

const Textarea = (props: React.TextareaHTMLAttributes<HTMLTextAreaElement>) => (
  <textarea {...props} className={`w-full bg-[#111] border border-white/10 p-4 text-gray-300 focus:outline-none focus:border-blue-500/30 text-sm leading-relaxed rounded-xl ${props.className || ''}`} />
);

const Admin: React.FC<AdminProps> = ({ projects, setProjects, about, setAbout, home, setHome, contact, setContact }) => {
  const [password, setPassword] = useState('');
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [activeTab, setActiveTab] = useState<'projects' | 'about' | 'hero' | 'contact'>('projects');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (password === 'admin9987') setIsAuthorized(true);
    else alert('Incorrect Password');
  };

  // --- Projects Logic ---
  const addProject = () => {
    const newProj: Project = {
      id: Date.now().toString(),
      title: 'New Project',
      role: 'Character Modeler',
      year: new Date().getFullYear().toString(),
      workTime: '4 Weeks',
      toolsUsed: ['Maya', 'ZBrush'],
      thumbnail: 'https://images.unsplash.com/photo-1614728263952-84ea206f99b6?auto=format&fit=crop&q=80&w=1280&h=720',
      description: 'Project description here...',
      detailRenders: [],
      clayRenders: [],
      wireframes: [],
      uvLayouts: [],
      turntableVideoUrl: '',
      technicalBreakdown: ''
    };
    setProjects([newProj, ...projects]);
  };
  const deleteProject = (id: string) => { if (confirm('Delete this project?')) setProjects(projects.filter(p => p.id !== id)); };
  const updateProject = (id: string, field: keyof Project, value: any) => { setProjects(projects.map(p => p.id === id ? { ...p, [field]: value } : p)); };

  // --- About/Lists Logic ---
  const addExp = () => {
    const newExp: Experience = { id: Date.now().toString(), company: 'Company', role: 'Role', period: '20XX-20XX', description: '', location: '' };
    setAbout({ ...about, experience: [newExp, ...about.experience] });
  };
  const updateExp = (id: string, field: keyof Experience, value: string) => {
    setAbout({ ...about, experience: about.experience.map(e => e.id === id ? { ...e, [field]: value } : e) });
  };
  const removeExp = (id: string) => setAbout({ ...about, experience: about.experience.filter(e => e.id !== id) });

  const addEdu = () => setAbout({ ...about, education: [...about.education, { degree: 'Degree', institution: 'School', year: '20XX', location: '' }] });
  const updateEdu = (index: number, field: any, value: string) => {
    const newEdu = [...about.education];
    newEdu[index] = { ...newEdu[index], [field]: value };
    setAbout({ ...about, education: newEdu });
  };
  const removeEdu = (index: number) => setAbout({ ...about, education: about.education.filter((_, i) => i !== index) });

  const addSkillCategory = () => setAbout({ ...about, tools: [...about.tools, { category: 'Category', items: [] }] });
  const updateSkillCategory = (index: number, value: string) => {
    const newTools = [...about.tools];
    newTools[index].category = value;
    setAbout({ ...about, tools: newTools });
  };
  const updateSkillItems = (index: number, value: string) => {
    const newTools = [...about.tools];
    newTools[index].items = value.split(',').map(s => s.trim()).filter(s => s !== '');
    setAbout({ ...about, tools: newTools });
  };
  const removeSkillCategory = (index: number) => setAbout({ ...about, tools: about.tools.filter((_, i) => i !== index) });

  if (!isAuthorized) {
    return (
      <div className="min-h-[70vh] flex items-center justify-center p-6 fade-in pt-40">
        <form onSubmit={handleLogin} className="w-full max-w-sm space-y-4 bg-white/5 p-8 border border-white/10 rounded-2xl">
          <h2 className="text-xl font-bold uppercase tracking-widest mb-6 text-center text-blue-500">Admin Console</h2>
          <input type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-[#111] border border-white/10 px-4 py-3 rounded-xl focus:outline-none focus:border-white/30 text-center" />
          <button type="submit" className="w-full bg-blue-600 text-white py-3 font-bold uppercase tracking-widest text-xs hover:bg-blue-500 transition-colors rounded-xl">Unlock</button>
        </form>
      </div>
    );
  }

  return (
    <div className="max-w-[1600px] mx-auto px-6 md:px-12 pt-40 fade-in pb-48">
      <div className="flex flex-col md:flex-row justify-between items-center mb-16 border-b border-white/5 pb-8 gap-6">
        <h1 className="text-2xl font-bold uppercase tracking-[0.2em] text-blue-500">MANAGEMENT</h1>
        <div className="flex flex-wrap justify-center gap-6 md:gap-8">
          {(['projects', 'hero', 'about', 'contact'] as const).map(tab => (
            <button 
              key={tab} 
              onClick={() => setActiveTab(tab)} 
              className={`text-[10px] uppercase tracking-widest font-bold pb-2 transition-all ${activeTab === tab ? 'border-b border-blue-500 text-white' : 'text-gray-500 hover:text-gray-300'}`}
            >
              {tab === 'hero' ? 'home' : tab}
            </button>
          ))}
        </div>
      </div>

      {activeTab === 'hero' && (
        <div className="max-w-4xl mx-auto p-10 bg-white/5 border border-white/10 rounded-2xl space-y-8 animate-fade-in">
          <h2 className="text-xl font-bold uppercase text-white border-b border-white/5 pb-4">Hero Section Settings</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div><Label>Display Name</Label><Input value={home.name} onChange={e => setHome({ ...home, name: e.target.value })} /></div>
            <div><Label>Professional Title</Label><Input value={home.professionalTitle} onChange={e => setHome({ ...home, professionalTitle: e.target.value })} /></div>
          </div>
          <div><Label>Hero Description</Label><Textarea rows={4} value={home.description} onChange={e => setHome({ ...home, description: e.target.value })} /></div>
          <div><Label>Hero Video Embed URL (YouTube/Vimeo)</Label><Input value={home.heroVideoUrl} onChange={e => setHome({ ...home, heroVideoUrl: e.target.value })} /></div>
        </div>
      )}

      {activeTab === 'contact' && (
        <div className="max-w-4xl mx-auto p-10 bg-white/5 border border-white/10 rounded-2xl space-y-8 animate-fade-in">
          <h2 className="text-xl font-bold uppercase text-white border-b border-white/5 pb-4">Contact Info Settings</h2>
          <div><Label>Public Email</Label><Input value={contact.email} onChange={e => setContact({ ...contact, email: e.target.value })} /></div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div><Label>ArtStation URL</Label><Input value={contact.artstationUrl} onChange={e => setContact({ ...contact, artstationUrl: e.target.value })} /></div>
            <div><Label>LinkedIn URL</Label><Input value={contact.linkedinUrl} onChange={e => setContact({ ...contact, linkedinUrl: e.target.value })} /></div>
          </div>
        </div>
      )}

      {activeTab === 'projects' && (
        <div className="space-y-12 animate-fade-in">
          <button onClick={addProject} className="w-full border border-dashed border-white/20 py-10 text-gray-500 hover:text-blue-500 hover:border-blue-500/40 transition-all uppercase tracking-[0.3em] text-[10px] font-bold rounded-2xl">+ Register New Project</button>
          {projects.map((p) => (
            <div key={p.id} className="p-10 bg-white/5 border border-white/10 space-y-8 relative group rounded-2xl shadow-2xl">
              <button onClick={() => deleteProject(p.id)} className="absolute top-6 right-8 text-red-900 hover:text-red-500 transition-colors uppercase text-[10px] font-bold tracking-widest">[REMOVE]</button>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-6">
                  <div><Label>Title</Label><Input value={p.title} onChange={e => updateProject(p.id, 'title', e.target.value)} /></div>
                  <div className="grid grid-cols-2 gap-4">
                    <div><Label>Role</Label><Input value={p.role} onChange={e => updateProject(p.id, 'role', e.target.value)} /></div>
                    <div><Label>Year</Label><Input value={p.year} onChange={e => updateProject(p.id, 'year', e.target.value)} /></div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div><Label>Duration</Label><Input value={p.workTime} onChange={e => updateProject(p.id, 'workTime', e.target.value)} /></div>
                    <div><Label>Tools (Comma sep)</Label><Input value={p.toolsUsed?.join(', ')} onChange={e => updateProject(p.id, 'toolsUsed', e.target.value.split(',').map(s=>s.trim()))} /></div>
                  </div>
                </div>
                <div className="space-y-6">
                  <div><Label>Thumbnail URL</Label><Input value={p.thumbnail} onChange={e => updateProject(p.id, 'thumbnail', e.target.value)} /></div>
                  <div><Label>Video Embed URL</Label><Input value={p.turntableVideoUrl} onChange={e => updateProject(p.id, 'turntableVideoUrl', e.target.value)} /></div>
                </div>
              </div>
              <div><Label>Overview</Label><Textarea rows={4} value={p.description} onChange={e => updateProject(p.id, 'description', e.target.value)} /></div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 border-t border-white/5 pt-8">
                <div><Label>Renders (URL per line)</Label><Textarea rows={6} value={p.detailRenders?.join('\n')} onChange={e => updateProject(p.id, 'detailRenders', e.target.value.split('\n').filter(s=>s!==''))} /></div>
                <div><Label>Clay (URL per line)</Label><Textarea rows={6} value={p.clayRenders?.join('\n')} onChange={e => updateProject(p.id, 'clayRenders', e.target.value.split('\n').filter(s=>s!==''))} /></div>
                <div><Label>Wire (URL per line)</Label><Textarea rows={6} value={p.wireframes?.join('\n')} onChange={e => updateProject(p.id, 'wireframes', e.target.value.split('\n').filter(s=>s!==''))} /></div>
                <div><Label>UV (URL per line)</Label><Textarea rows={6} value={p.uvLayouts?.join('\n')} onChange={e => updateProject(p.id, 'uvLayouts', e.target.value.split('\n').filter(s=>s!==''))} /></div>
              </div>
              <div><Label>Tech Breakdown</Label><Textarea rows={3} value={p.technicalBreakdown} onChange={e => updateProject(p.id, 'technicalBreakdown', e.target.value)} /></div>
            </div>
          ))}
        </div>
      )}

      {activeTab === 'about' && (
        <div className="space-y-12 animate-fade-in">
          <div className="p-10 bg-white/5 border border-white/10 rounded-2xl"><Label>Intro Summary</Label><Textarea rows={6} value={about.intro} onChange={e => setAbout({ ...about, intro: e.target.value })} /></div>

          <div className="space-y-8">
            <div className="flex justify-between items-center"><h3 className="font-bold uppercase tracking-widest text-white">Experience</h3><button onClick={addExp} className="text-xs text-blue-500 font-bold tracking-widest">+ ADD EXP</button></div>
            {about.experience.map(exp => (
