// Helper function to sanitize YouTube URLs for iframe usage
const sanitizeYoutubeUrl = (url: string): string => {
  if (!url) return '';
  const match = url.match(/(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
  if (match && match[1]) {
    return `https://www.youtube.com/embed/${match[1]}`;
  }
  return url;
};

// Helper function to sanitize Image URLs (especially Dropbox) for direct display
const sanitizeImageUrl = (url: string): string => {
  if (!url) return '';
  let cleanUrl = url.trim();
  // Dropbox conversion
  if (cleanUrl.includes('dropbox.com')) {
    cleanUrl = cleanUrl
      .replace('www.dropbox.com', 'dl.dropboxusercontent.com')
      .split('?')[0]; // Remove ?dl=0 or other query params
  }
  return cleanUrl;
};

