// Helper function to sanitize Video URLs (YouTube, Google Drive, Dropbox) for iframe usage
const sanitizeVideoUrl = (url: string): string => {
  if (!url) return '';
  let cleanUrl = url.trim();

  // YouTube
  const ytMatch = cleanUrl.match(/(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:watch\?v=|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
  if (ytMatch && ytMatch[1]) {
    return `https://www.youtube.com/embed/${ytMatch[1]}`;
  }

  // Google Drive Video
  if (cleanUrl.includes('drive.google.com')) {
    const driveMatch = cleanUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    if (driveMatch && driveMatch[1]) {
      return `https://drive.google.com/file/d/${driveMatch[1]}/preview`;
    }
  }

  // Dropbox Video (Direct stream)
  if (cleanUrl.includes('dropbox.com')) {
    return cleanUrl.replace('www.dropbox.com', 'dl.dropboxusercontent.com').split('?')[0];
  }

  return cleanUrl;
};

// Helper function to sanitize Image URLs (Dropbox, Google Drive) for direct display
const sanitizeImageUrl = (url: string): string => {
  if (!url) return '';
  let cleanUrl = url.trim();

  // Dropbox conversion
  if (cleanUrl.includes('dropbox.com')) {
    cleanUrl = cleanUrl
      .replace('www.dropbox.com', 'dl.dropboxusercontent.com')
      .split('?')[0]; 
  }

  // Google Drive Image conversion
  if (cleanUrl.includes('drive.google.com')) {
    const driveMatch = cleanUrl.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);
    if (driveMatch && driveMatch[1]) {
      return `https://drive.google.com/uc?export=view&id=${driveMatch[1]}`;
    }
  }

  return cleanUrl;
};

