import { Project, AboutData, HomeData, ContactData } from './types';
import { INITIAL_PROJECTS, INITIAL_ABOUT, INITIAL_HOME, INITIAL_CONTACT } from './data';

// Pages
import Home from './pages/Home';
import ProjectDetail from './pages/ProjectDetail';
import Admin from './pages/Admin';

const Navbar: React.FC = () => {
  const location = useLocation();
  const navigate = useNavigate();
  const [activeSection, setActiveSection] = useState('home');
  const isScrollingRef = useRef(false);
  const scrollTimeoutRef = useRef<number | null>(null);
  const sectionRatios = useRef<Record<string, number>>({});

  useEffect(() => {
    if (location.pathname !== '/') {
      setActiveSection('');
      return;
    }

    const observerOptions = {
      root: null,
      rootMargin: '-10% 0px -70% 0px', // 스크롤 감지 영역 조정
      threshold: [0, 0.5, 1.0]
    };

    const observerCallback = (entries: IntersectionObserverEntry[]) => {
      if (isScrollingRef.current) return;
      entries.forEach((entry) => {
        sectionRatios.current[entry.target.id] = entry.intersectionRatio;
      });
      const entriesList = Object.entries(sectionRatios.current) as [string, number][];
      const winner = entriesList.reduce<{ id: string; ratio: number }>(
        (max, [id, ratio]) => (ratio > max.ratio ? { id, ratio } : max),
        { id: 'home', ratio: 0 }
      );
      if (winner.ratio > 0.1) {
        setActiveSection(winner.id);
      }
    };

    const observer = new IntersectionObserver(observerCallback, observerOptions);
    const sectionIds = ['home', 'projects', 'about', 'contact'];
    sectionIds.forEach(id => {
      const el = document.getElementById(id);
      if (el) observer.observe(el);
    });

    return () => observer.disconnect();
  }, [location.pathname]);

  const scrollToSection = useCallback((id: string) => {
    const performScroll = () => {
      const el = document.getElementById(id);
      if (el) {
        const offset = 120; 
        const elementPosition = el.getBoundingClientRect().top + window.pageYOffset;
        const offsetPosition = elementPosition - offset;

        isScrollingRef.current = true;
        setActiveSection(id);

        window.scrollTo({
          top: id === 'home' ? 0 : offsetPosition,
          behavior: 'smooth'
        });

        if (scrollTimeoutRef.current) window.clearTimeout(scrollTimeoutRef.current);
        scrollTimeoutRef.current = window.setTimeout(() => {
          isScrollingRef.current = false;
        }, 1200);
      }
    };

    if (location.pathname !== '/') {
      navigate('/');
      setTimeout(performScroll, 150);
    } else {
      performScroll();
    }
  }, [location.pathname, navigate]);

  const navLinkClass = (id: string) => {
    const isActive = activeSection === id;
    return `${isActive ? 'text-blue-500' : 'text-gray-500'} hover:text-white transition-all duration-300 uppercase cursor-pointer relative py-2 text-[11px] md:text-[12px] font-bold tracking-[0.3em] outline-none`;
  };

  return (
    <nav className="fixed top-0 left-0 w-full z-50 h-24 flex items-center pointer-events-none">
      <div className="max-w-[1800px] mx-auto w-full px-8 md:px-16 flex items-center justify-center">
        {/* Only this inner container has pointer-events-auto */}
        <div className="flex gap-8 md:gap-16 items-center opacity-100 translate-y-0 pointer-events-auto">
          <button onClick={() => scrollToSection('home')} className={navLinkClass('home')}>HOME</button>
          <button onClick={() => scrollToSection('projects')} className={navLinkClass('projects')}>PROJECTS</button>
          <button onClick={() => scrollToSection('about')} className={navLinkClass('about')}>ABOUT</button>
          <button onClick={() => scrollToSection('contact')} className={navLinkClass('contact')}>CONTACT</button>
        </div>
      </div>
    </nav>
  );
};

const Footer: React.FC = () => (
  <footer className="py-20 px-8 md:px-16 border-t border-white/5 bg-[#0b0e14]">
    <div className="max-w-[1800px] mx-auto flex flex-col md:flex-row justify-between items-center gap-10">
      <div className="space-y-2 text-center md:text-left">
        <p className="text-blue-500 font-bold tracking-tight text-lg uppercase">HEEJI WOO</p>
        <p className="text-gray-600 text-[10px] uppercase tracking-[0.4em] font-bold">©2026 HEEJI WOO. ALL RIGHTS RESERVED</p>
      </div>
      <Link to="/admin" className="text-[#151920] hover:text-blue-900/40 transition-colors text-[8px] font-normal tracking-widest uppercase">CONSOLE</Link>
    </div>
  </footer>
);

const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>(() => {
    const saved = localStorage.getItem('hw_projects');
    return saved ? JSON.parse(saved) : INITIAL_PROJECTS;
  });

  const [about, setAbout] = useState<AboutData>(() => {
    const saved = localStorage.getItem('hw_about');
    return saved ? JSON.parse(saved) : INITIAL_ABOUT;
  });

  const [home, setHome] = useState<HomeData>(() => {
    const saved = localStorage.getItem('hw_home');
    return saved ? JSON.parse(saved) : INITIAL_HOME;
  });

  const [contact, setContact] = useState<ContactData>(() => {
    const saved = localStorage.getItem('hw_contact');
    return saved ? JSON.parse(saved) : INITIAL_CONTACT;
  });

  useEffect(() => { localStorage.setItem('hw_projects', JSON.stringify(projects)); }, [projects]);
  useEffect(() => { localStorage.setItem('hw_about', JSON.stringify(about)); }, [about]);
  useEffect(() => { localStorage.setItem('hw_home', JSON.stringify(home)); }, [home]);
  useEffect(() => { localStorage.setItem('hw_contact', JSON.stringify(contact)); }, [contact]);

  return (
    <HashRouter>
      <div className="min-h-screen flex flex-col">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home projects={projects} about={about} home={home} contact={contact} />} />
            <Route path="/projects/:id" element={<ProjectDetail projects={projects} />} />
            <Route path="/admin" element={<Admin 
              projects={projects} setProjects={setProjects} 
              about={about} setAbout={setAbout} 
              home={home} setHome={setHome}
              contact={contact} setContact={setContact}
            />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </HashRouter>
  );
};

export default App;

