const App: React.FC = () => {
  const [projects, setProjects] = useState<Project[]>(() => {
    const saved = localStorage.getItem('hw_projects');
    return saved ? JSON.parse(saved) : INITIAL_PROJECTS;
  });

  const [about, setAbout] = useState<AboutData>(() => {
    const saved = localStorage.getItem('hw_about');
    return saved ? JSON.parse(saved) : INITIAL_ABOUT;
  });

  const [home, setHome] = useState<HomeData>(() => {
    const saved = localStorage.getItem('hw_home');
    return saved ? JSON.parse(saved) : INITIAL_HOME;
  });

  const [contact, setContact] = useState<ContactData>(() => {
    const saved = localStorage.getItem('hw_contact');
    return saved ? JSON.parse(saved) : INITIAL_CONTACT;
  });

  useEffect(() => { localStorage.setItem('hw_projects', JSON.stringify(projects)); }, [projects]);
  useEffect(() => { localStorage.setItem('hw_about', JSON.stringify(about)); }, [about]);
  useEffect(() => { localStorage.setItem('hw_home', JSON.stringify(home)); }, [home]);
  useEffect(() => { localStorage.setItem('hw_contact', JSON.stringify(contact)); }, [contact]);

  return (
    <HashRouter>
      <div className="min-h-screen flex flex-col">
        <Navbar />
        <main className="flex-grow">
          <Routes>
            <Route path="/" element={<Home projects={projects} about={about} home={home} contact={contact} />} />
            <Route path="/projects/:id" element={<ProjectDetail projects={projects} />} />
            <Route path="/admin" element={<Admin 
              projects={projects} setProjects={setProjects} 
              about={about} setAbout={setAbout} 
              home={home} setHome={setHome}
              contact={contact} setContact={setContact}
            />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </HashRouter>
  );
};

export default App;

